/*
 * A075035  Numbers k such that tau(k) >= tau(k+1) >= tau(k+2) >= tau(k+3)
 *          where tau(k) = number of divisors of k.
 * https://oeis.org/A075035
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n-th integer k such that tau(k) ≥ tau(k+1) ≥
 *            tau(k+2) ≥ tau(k+3), where tau(m) = number of positive divisors
 *            of m. The sequence is generated by scanning k sequentially and
 *            storing the qualifying values. The implementation uses a simple
 *            sieve to pre‑compute primes up to 2 000 000, then...
 * Range:     u8 n <= 18, u16 n <= 3909, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

#define PRIME_SIEVE_LIMIT 2000000      /* enough for k up to ~4×10¹² */

static int  *prime_list   = NULL;     /* array of primes */
static size_t prime_count = 0;        /* number of primes stored */

/* Allocate and fill prime_list with all primes ≤ PRIME_SIEVE_LIMIT */
static void init_primes(void)
{
    if (prime_list != NULL) return;               /* already done */

    size_t limit = PRIME_SIEVE_LIMIT;
    bool *is_composite = (bool*)malloc(limit + 1);
    if (!is_composite) abort();
    for (size_t i = 0; i <= limit; ++i) is_composite[i] = false;

    size_t cnt = 0;
    for (size_t i = 2; i * i <= limit; ++i)
        if (!is_composite[i])
            for (size_t j = i * i; j <= limit; j += i)
                is_composite[j] = true;

    for (size_t i = 2; i <= limit; ++i)
        if (!is_composite[i]) ++cnt;

    prime_list = (int*)malloc(cnt * sizeof(int));
    if (!prime_list) abort();

    size_t idx = 0;
    for (size_t i = 2; i <= limit; ++i)
        if (!is_composite[i]) prime_list[idx++] = (int)i;

    prime_count = cnt;
    free(is_composite);
}

/* Compute tau(m) for m ≤ 64‑bit using the pre‑computed prime list. */
static uint64_t tau_u64(uint64_t m)
{
    if (m <= 1) return 1;
    uint64_t res = 1;
    uint64_t rem = m;
    for (size_t i = 0; i < prime_count && (uint64_t)prime_list[i] * (uint64_t)prime_list[i] <= rem; ++i)
    {
        int p = prime_list[i];
        if (rem % p == 0)
        {
            uint64_t e = 1;
            rem /= p;
            while (rem % p == 0) { rem /= p; ++e; }
            res *= (e + 1);
        }
    }
    if (rem > 1) res *= 2;          /* remaining prime factor */
    return res;
}

/* Cache of the sequence terms */
static seq_t *cache   = NULL;     /* dynamic array of seq_t */
static size_t cache_used = 0;     /* number of terms stored */
static size_t cache_cap  = 0;     /* capacity of the array */

/* Ensure cache has at least 'need' capacity */
static void ensure_cache_cap(size_t need)
{
    if (cache_cap >= need) return;
    size_t new_cap = (cache_cap == 0) ? 16 : cache_cap;
    while (new_cap < need) new_cap <<= 1;
    seq_t *new_arr = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_arr) abort();
    cache = new_arr;
    cache_cap = new_cap;
}

/* Append a new term to the cache */
static void add_term(seq_t val)
{
    ensure_cache_cap(cache_used + 1);
    cache[cache_used++] = val;
}

/* Main function to compute the nth term.  n is 1‑based. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;                /* undefined; return 0 */

    init_primes();                              /* initialise primes once */

    /* Generate terms until we have n of them. */
    static idx_t next_k = 1;                     /* next integer to test */

    while (cache_used < n)
    {
        uint64_t k   = (uint64_t)next_k;
        uint64_t tau1 = tau_u64(k);
        uint64_t tau2 = tau_u64(k + 1);
        uint64_t tau3 = tau_u64(k + 2);
        uint64_t tau4 = tau_u64(k + 3);

        if (tau1 >= tau2 && tau2 >= tau3 && tau3 >= tau4)
            add_term((seq_t)k);

        ++next_k;
    }

    return cache[n - 1];
}
